/**
 * Label and value pairs describing one entity (`design/components/description-list.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/description-list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Render,
  isTemplate,
  useMember,
  type Each,
  type NodeTemplate,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/description-list.module.css'

export interface DescriptionListItem {
  term: string
  detail: NodeTemplate | string
}

export type DescriptionListOrientation = NonNullable<DescriptionListProps['orientation']>

/** Label and value pairs describing one entity: the inputs it takes, by the React member's prop names. */
export interface DescriptionListProps {
  /**
   * Rendered in the order given (Stat's rule: sorting is data logic).
   */
  items: DescriptionListItem[]
  /**
   * `vertical` (default) stacks term over detail and works at any width, as in Timeline, because
   * metadata often sits in a narrow aside. `horizontal` puts a term column beside the details.
   */
  orientation?: 'horizontal' | 'vertical'
}

/** Label and value pairs describing one entity. */
@Component({
  selector: 'pm-description-list',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Render],
  // prettier-ignore
  template: `@if (e1()) {<dl
[attr.class]="e2()"
[attr.data-orientation]="e3()"
data-member="description-list"
>@for (item of e4(); track e5($index); let index = $index) {<div
[attr.class]="e6()"
><dt
[attr.class]="e7()"
>{{ e8(item) }}</dt>
<dd
[attr.class]="e9()"
>@if (e10(item)) {{{ e11(item) }}} @else {@if (template(e12(item))) {<ng-container [pmRender]="e12(item)" />} @else {{{ e12(item) }}}}</dd></div>}</dl>}`,
})
export class DescriptionList {
  /**
   * Rendered in the order given (Stat's rule: sorting is data logic).
   */
  readonly items = input.required<DescriptionListProps['items']>()
  /**
   * `vertical` (default) stacks term over detail and works at any width, as in Timeline, because
   * metadata often sits in a narrow aside. `horizontal` puts a term column beside the details.
   */
  readonly orientation = input<
    Exclude<DescriptionListProps['orientation'], undefined>,
    DescriptionListProps['orientation']
  >('vertical', {
    transform: (value: DescriptionListProps['orientation']) =>
      value === undefined ? 'vertical' : value,
  })
  protected readonly $ = useMember({
    events: [],
    props: { items: () => this.items(), orientation: () => this.orientation() },
  })
  protected readonly $p = this.$.props
  protected readonly template = isTemplate

  protected e1() {
    return this.$p.items.length > 0
  }

  protected e2() {
    if (!(this.$p.items.length > 0)) return undefined as never
    return styles.root
  }

  protected e3() {
    if (!(this.$p.items.length > 0)) return undefined as never
    return this.$p.orientation
  }

  e4() {
    if (!(this.$p.items.length > 0)) return undefined as never
    return this.$p.items
  }

  protected e5(index: number) {
    return index
  }

  protected e6() {
    if (!(this.$p.items.length > 0)) return undefined as never
    return styles.pair
  }

  protected e7() {
    if (!(this.$p.items.length > 0)) return undefined as never
    return styles.term
  }

  protected e8(item: Each<ReturnType<DescriptionList['e4']>>) {
    if (!(this.$p.items.length > 0)) return undefined as never
    return item.term
  }

  protected e9() {
    if (!(this.$p.items.length > 0)) return undefined as never
    return styles.detail
  }

  protected e10(item: Each<ReturnType<DescriptionList['e4']>>) {
    if (!(this.$p.items.length > 0)) return undefined as never
    return typeof item.detail === 'string'
  }

  protected e11(item: Each<ReturnType<DescriptionList['e4']>>) {
    if (!(this.$p.items.length > 0)) return undefined as never
    if (!(typeof item.detail === 'string')) return undefined as never
    return item.detail
  }

  protected e12(item: Each<ReturnType<DescriptionList['e4']>>) {
    if (!(this.$p.items.length > 0)) return undefined as never
    if (typeof item.detail === 'string') return undefined as never
    return item.detail
  }
}
